def min_patches_brute(nums, n):
    current = list(nums)
    patches = 0
    while True:
        achievable = {0}
        for x in current:                             # recompute ALL achievable sums from scratch
            achievable |= {s + x for s in achievable}
        missing = next((v for v in range(1, n + 1) if v not in achievable), None)
        if missing is None:
            return patches
        current.append(missing)
        patches += 1

