def min_patches(nums, n):
    miss = 1                                            # smallest sum not yet achievable
    added = 0
    i = 0
    while miss <= n:
        if i < len(nums) and nums[i] <= miss:
            miss += nums[i]                                # consume this number for free
            i += 1
        else:
            miss += miss                                     # patch with exactly 'miss'
            added += 1
    return added

