int minPatches(vector<int>& nums, int n) {
    long long miss = 1;                                       // smallest sum not yet achievable
    int added = 0, i = 0;
    while (miss <= n) {
        if (i < (int)nums.size() && nums[i] <= miss) {
            miss += nums[i];                                    // consume this number for free
            i++;
        } else {
            miss += miss;                                         // patch with exactly 'miss'
            added++;
        }
    }
    return added;
}
